  temp=qpath.with_suffix('.b000029.tmp');temp.write_text(json.dumps(q,ensure_ascii=False,indent=2));temp.replace(qpath)
  b.save(b.E/'source-queue-update-verification.json',dict(at=b.h.now(),before_sha256=b.h.sha(json.dumps(before,sort_keys=True).encode()),after_file_sha256=b.h.sha(qpath.read_bytes()),updated_sources=['vam','princeton_art_museum'],unrelated_entries_preserved=True,entries=[pr,va]))
